('80', 'Voluptas omnis', 'voluptas-omnis', 'Voluptatem sit ratione rerum sit. Delectus quae harum suscipit excepturi quas laborum. Ratione ea natus aspernatur sed. Officia a soluta minus laboriosam officiis necessitatibus.', NULL, NULL, NULL, NULL, NULL, NULL, 'Draft', '1', '1', NULL, '2026-06-24 11:06:15', '2026-06-24 11:06:15', NULL),
('81', 'Culpa pariatur', 'culpa-pariatur', 'Animi explicabo sint at et pariatur fugit. Eveniet ea enim odio. Ullam sit consequatur rerum temporibus et. Porro cupiditate aut minima voluptatibus atque vero voluptas quas.', NULL, NULL, NULL, NULL, NULL, NULL, 'Draft', '1', '1', NULL, '2026-06-24 11:06:15', '2026-06-24 11:06:15', NULL),
('82', 'Quia aliquid', 'quia-aliquid', 'Nam libero accusantium perferendis. Atque iure molestias qui in veniam nesciunt. Voluptatem molestiae quia delectus.', NULL, NULL, NULL, NULL, NULL, NULL, 'Active', '1', '1', NULL, '2026-06-24 11:06:15', '2026-06-24 11:06:15', NULL),
('83', 'Ipsa dolorem', 'ipsa-dolorem', 'Aut ut quos tempora velit corrupti dignissimos dolorem dignissimos. Nesciunt placeat unde et. Labore voluptatibus aliquid ut.', NULL, NULL, NULL, NULL, NULL, NULL, 'Inactive', '1', '1', NULL, '2026-06-24 11:06:15', '2026-06-24 11:06:15', NULL),
('84', 'Quia numquam', 'quia-numquam', 'Sed velit sunt optio libero. Aut consequuntur nam ut sed dolor. Magni enim quam ipsum consequatur rem dignissimos.', NULL, NULL, NULL, NULL, NULL, NULL, 'Draft', '1', '1', NULL, '2026-06-24 11:06:15', '2026-06-24 11:06:15', NULL),
('85', 'Doloribus id', 'doloribus-id', 'Labore quaerat nulla qui tempore quos vel quis ratione. Sed deleniti recusandae quasi accusamus molestias. Facilis in repellat cupiditate rerum. Laudantium vel velit sunt quos repellendus sapiente inventore.', NULL, NULL, NULL, NULL, NULL, NULL, 'Draft', '1', '1', NULL, '2026-06-24 11:06:15', '2026-06-24 11:06:15', NULL);
